begin;
create or replace function public.nexus_city_recalculate(p_user uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare c public.nexus_cities;buildings integer;districts integer;displays integer;xp bigint;lvl integer;tier integer;begin select * into c from public.nexus_cities where user_id=p_user for update;if not found then raise exception 'Ville introuvable';end if;select count(*) into buildings from public.nexus_city_placements where city_id=c.city_id;select count(*) into districts from public.nexus_city_districts where city_id=c.city_id and unlocked=true;select count(*) into displays from public.nexus_city_collectible_displays where city_id=c.city_id;xp=buildings*100+greatest(0,districts-1)*500+displays*150+least(c.visitors,10000);lvl=least(50,greatest(1,(xp/1000)::integer+1));tier=least(10,greatest(1,(lvl/5)::integer+1));update public.nexus_cities set city_xp=xp,city_level=lvl,land_tier=tier,city=jsonb_set(jsonb_set(city,'{level}',to_jsonb(lvl),true),'{xp}',to_jsonb(xp),true),updated_at=now() where city_id=c.city_id;return jsonb_build_object('xp',xp,'level',lvl,'landTier',tier);end;$$;
create or replace function public.nexus_city_environment(p_user uuid,p_day text,p_weather text,p_ambience text) returns boolean language plpgsql security invoker set search_path='' as $$begin if p_day not in ('auto','day','night') or p_weather not in ('clear','rain','fog','snow','storm') or p_ambience not in ('matrix','gold','urban','cinematic','calm') then raise exception 'Ambiance invalide';end if;update public.nexus_cities set day_mode=p_day,weather=p_weather,ambience=p_ambience,revision=revision+1,updated_at=now() where user_id=p_user;if not found then raise exception 'Ville introuvable';end if;return true;end;$$;
create or replace function public.nexus_city_favorite(p_user uuid,p_city uuid,p_add boolean) returns boolean language plpgsql security invoker set search_path='' as $$begin if not exists(select 1 from public.nexus_cities where city_id=p_city and visibility='public') then raise exception 'Ville indisponible';end if;if p_add then insert into public.nexus_city_favorites(user_id,city_id) values(p_user,p_city) on conflict do nothing;else delete from public.nexus_city_favorites where user_id=p_user and city_id=p_city;end if;return true;end;$$;
revoke all on function public.nexus_city_recalculate(uuid),public.nexus_city_environment(uuid,text,text,text),public.nexus_city_favorite(uuid,uuid,boolean) from public,anon,authenticated;grant execute on function public.nexus_city_recalculate(uuid),public.nexus_city_environment(uuid,text,text,text),public.nexus_city_favorite(uuid,uuid,boolean) to service_role;
commit;
